<?php $av=[];foreach($availability as $row)$av[(int)$row['weekday']]=$row;$days=[1=>'Segunda',2=>'Terça',3=>'Quarta',4=>'Quinta',5=>'Sexta',6=>'Sábado',7=>'Domingo'];?>
<div class="section-heading"><div><div class="eyebrow">Minha agenda</div><h1>Minha disponibilidade</h1><p class="text-secondary mb-0">Defina quando os clientes poderão encontrar horários livres no seu link público.</p></div></div>
<div class="card"><div class="card-body"><form method="post" action="/professional/availability"><?php echo \App\Core\CSRF::field();?><div class="row g-2"><?php foreach($days as $i=>$label):$r=$av[$i]??null;$enabled=$r&&$r['active'];?><div class="col-12"><div class="row align-items-center g-2 border-bottom py-3"><div class="col-md-3"><label class="form-check"><input class="form-check-input" type="checkbox" name="day_<?=$i?>" value="1" <?=$enabled?'checked':''?>> <strong><?=$label?></strong></label></div><div class="col"><label class="small text-secondary">Início</label><input class="form-control" type="time" name="start_<?=$i?>" value="<?=htmlspecialchars(substr((string)($r['start_time']??'09:00'),0,5))?>"></div><div class="col"><label class="small text-secondary">Fim</label><input class="form-control" type="time" name="end_<?=$i?>" value="<?=htmlspecialchars(substr((string)($r['end_time']??'18:00'),0,5))?>"></div></div></div><?php endforeach;?></div><button class="btn btn-primary mt-4">Salvar minha disponibilidade</button></form></div></div>
